pub trait BoolResult {
    fn ok_or_err<E>(self, err: E) -> Result<(), E>;
}

impl BoolResult for bool {
    #[inline]
    fn ok_or_err<E>(self, err: E) -> Result<(), E> {
        if self {
            Ok(())
        } else {
            Err(err)
        }
    }
}

/// The WARP accumulator. Holds the protocol configuration plus the
/// caller-supplied cryptographic primitives (code, relation, Merkle
/// scheme). Everything here is set once at `new()` and read-only
/// thereafter.
pub struct WARP<
    F: PrimeField,
    P: BundledPESAT<F>,
    C: LinearCode<F> + Clone,
    H: hasher::WarpHasher<F>,
> {
    pub config: WARPConfig<F, P>,
    pub code: C,
    pub p: P,
    pub scheme: MerkleCommitment<H, PerfectBinary>,
}

impl<
        F: PrimeField,
        P: Clone + BundledPESAT<F, Config = (usize, usize, usize)>, // m, n, k
        C: LinearCode<F> + Clone,
        H: hasher::WarpHasher<F>,
    > WARP<F, P, C, H>
{
    /// Create a fresh WARP instance from a user-supplied hasher. The
    /// hasher choice drives the prove/verify cost profile: Blake3 for
    /// prover speed, Poseidon2 for circuit-friendly recursion.
    pub fn new(config: WARPConfig<F, P>, code: C, p: P, hasher: H) -> WARP<F, P, C, H> {
        let scheme = MerkleCommitment::<H, PerfectBinary>::new(
            hasher,
            PerfectBinary::with_num_leaves(code.code_len()),
        );
        Self {
            config,
            code,
            p,
            scheme,
        }
    }
}

impl<
        F: PrimeField + Encoding<[u8]> + Decoding<[u8]> + NargDeserialize + NargSerialize,
        P: Clone + BundledPESAT<F, Constraints = R1CSConstraints<F>, Config = (usize, usize, usize)>, // m, n, k
        C: LinearCode<F> + Clone,
        H: hasher::WarpHasher<F>,
    > AccumulationScheme<F, H> for WARP<F, P, C, H>
{
    type Index = P;
    type ProverKey = (P, usize, usize, usize);
    type VerifierKey = (usize, usize, usize);
    type Instances = Vec<Vec<F>>;
    type Witnesses = Vec<Vec<F>>;

    fn index(
        prover_state: &mut ProverState,
        index: Self::Index,
    ) -> spongefish::VerificationResult<(Self::ProverKey, Self::VerifierKey)> {
        let (m, n, k) = index.config();
        // Absorb the public parameters into the transcript before any
        // challenges are drawn. TODO: hoist these three `prover_message`
        // calls behind a `public_parameters!` helper once the generic
        // `BundledPESAT::config()` shape is settled — today's `(m, n, k)`
        // is R1CS-specific.
        prover_state.public_message(&index.description());
        prover_state.prover_message(&F::from(m as u32));
        prover_state.prover_message(&F::from(n as u32));
        prover_state.prover_message(&F::from(k as u32));
        Ok(((index, m, n, k), (m, n, k)))
    }

    #[tracing::instrument(name = "warp.prove", skip_all)]
    fn prove(
        &self,
        pk: Self::ProverKey,
        prover_state: &mut ProverState,
        witnesses: Self::Witnesses,
        instances: Self::Instances,
        acc_instance: AccumulatorInstance<F, H>,
        acc_witness: AccumulatorWitness<F, H>,
    ) -> ProveResult<F, H> {
        debug_assert!(instances.len() > 1);
        debug_assert_eq!(witnesses.len(), instances.len());
        debug_assert_eq!(acc_witness.td.len(), acc_instance.rt.len());

        let (l1, l) = (self.config.l1, self.config.l);
        let l2 = l - l1;
        debug_assert_eq!(l1 + l2, l);
        debug_assert!(l.is_power_of_two());

        // Parse phase: dimensions and transcript priming.
        #[allow(non_snake_case)]
        let (M, N, k) = (pk.1, pk.2, pk.3);
        let (log_m, log_l) = (log2(M) as usize, log2(l) as usize);
        let log_n = log2(self.code.code_len()) as usize;

        debug_assert_eq!(instances[0].len(), N - k);
        absorb_instances(prover_state, &instances);
        acc_instance.absorb_into(prover_state);

        let AccumulatorWitness {
            td: acc_tds,
            f: acc_fs,
            w: acc_ws,
        } = acc_witness;

        // Phase 2: PESAT — emit oracles (codewords), commit, squeeze τs.
        let pesat = pesat::prove::<F, C, H>(
            prover_state,
            &self.code,
            &self.scheme,
            &witnesses,
            l1,
            log_m,
        );

        // Phase 3a: twin-constraint sumcheck.
        let tc = twin_constraint::prove::<F, H>(
            prover_state,
            &pesat.codewords,
            pesat.taus,
            acc_instance,
            &acc_fs,
            &acc_ws,
            &instances,
            &witnesses,
            self.p.constraints(),
            log_l,
            log_m,
            log_n,
        );

        // Phase 3b: bundled η, ν₀, new commitment, absorb.
        let beta_prep = EqPolyPrep::new(&tc.beta_tau);
        let beta_eq_evals = (0..M).map(|i| beta_prep.eval(i)).collect::<Vec<_>>();
        let eta = self
            .p
            .evaluate_bundled(&beta_eq_evals, &tc.z)
            .map_err(|_| ProverError::SpongeFish)?;
        let nu_0 = tc.f.query_at_point(&tc.zeta_0);

        let (new_x, new_w) = tc.z.split_at(N - k);
        let new_x = new_x.to_vec();
        let new_w = new_w.to_vec();
        let new_beta = (vec![tc.beta_tau.clone()], vec![new_x]);

        // New-oracle commit: single-element leaves (one F per position).
        let td = {
            let _s = tracing::info_span!("warp.commit_new_oracle").entered();
            count_ops!(MerkleTreeBuilds);
            let leaves: Vec<Vec<F>> = tc.f.evals().iter().map(|&x| vec![x]).collect();
            self.scheme.commit(&leaves)
        };
        let td_root: H::Digest = td.root().clone();
        prover_state.prover_message(&td_root);
        prover_state.prover_message(&eta);
        prover_state.prover_message(&nu_0);

        // Phase 3c: OOD — point queries on the oracle.
        let ood_out = ood::prove::<F>(prover_state, &tc.f, self.config.s, log_n);

        // Sample shift queries — ordering-coupled to the batching ξ below.
        let queries = QueryIndices::<F>::sample(prover_state, log_n, self.config.t);

        // Phase 3d: batching sumcheck.
        let ood_chunks: Vec<&[F]> = ood_out.samples_flat.chunks(log_n).collect();
        let mut zetas: Vec<&[F]> = Vec::with_capacity(1 + self.config.s + self.config.t);
        zetas.push(tc.zeta_0.as_slice());
        zetas.extend(ood_chunks);
        zetas.extend(queries.evaluation_points.iter().map(|v| v.as_slice()));

        let batching_out = batching::prove::<F>(
            prover_state,
            &tc.f,
            &zetas,
            self.config.s,
            self.config.t,
            log_n,
        );

        // Phase 3e: proximity — ark-vc scheme.open produces one pruned
        // proof per committed tree.
        let all_codewords: Vec<Vec<F>> = acc_fs.into_iter().chain(pesat.codewords).collect();
        let prox = proximity::prove::<F, H>(
            &self.scheme,
            &queries,
            &pesat.td_0,
            &acc_tds,
            &all_codewords,
        );

        // Assemble new accumulator state and proof.
        let mut nus = Vec::with_capacity(1 + self.config.s);
        nus.push(nu_0);
        nus.extend(ood_out.answers);

        let new_acc_instance = AccumulatorInstance {
            rt: vec![td_root],
            alpha: vec![batching_out.alpha],
            mu: vec![batching_out.mu],
            beta: new_beta,
            eta: vec![eta],
        };
        let new_acc_witness = AccumulatorWitness {
            td: vec![td],
            f: vec![tc.f.into_evals()],
            w: vec![new_w],
        };
        let proof = WARPProof {
            rt_0: pesat.td_0.root().clone(),
            mu_i: pesat.mus,
            nu_0,
            nu_i: nus,
            auth_0: prox.auth_0,
            auth_j: prox.auth_j,
            shift_query_answers: prox.shift_query_answers,
        };

        Ok(((new_acc_instance, new_acc_witness), proof))
    }

    fn verify<'a>(
        &self,
        vk: Self::VerifierKey,
        verifier_state: &mut VerifierState<'a>,
        acc_instance: AccumulatorInstance<F, H>,
        proof: WARPProof<F, H>,
    ) -> Result<(), VerifierError> {
        let (l1, l) = (self.config.l1, self.config.l);
        let l2 = l - l1;

        ////////////////////////
        // 1. Parsing phase
        ////////////////////////
        // a. verification key
        #[allow(non_snake_case)]
        let (M, N, k) = (vk.0, vk.1, vk.2);
        let (log_m, log_l) = (log2(M) as usize, log2(l) as usize);

        let n = self.code.code_len();
        let log_n = log2(n) as usize;

        // f. absorb parameters
        let (
            l1_xs,
            AccumulatorInstance {
                rt: l2_roots,
                alpha: l2_alphas,
                mu: l2_mus,
                beta: (l2_taus, l2_xs),
                eta: l2_etas,
            },
        ) = parse_statement::<F, H>(verifier_state, l1, l2, N - k, log_n, log_m)?;

        ////////////////////////
        // 2. Derive randomness
        ////////////////////////
        let DerivedRandomness {
            rt_0,
            l1_mus,
            l1_taus,
            omega,
            tau,
            gamma_sumcheck,
            coeffs_twinc_sumcheck,
            td: _,
            eta,
            mut nus,
            ood_samples,
            bytes_shift_queries,
            xi,
            alpha_sumcheck,
            sums_batching_sumcheck,
        } = derive_randomness::<F, H>(
            verifier_state,
            l1,
            log_n,
            log_l,
            self.config.s,
            self.config.t,
            log_m,
        )?;

        let r = 1 + self.config.s + self.config.t;
        let log_r = log2(r) as usize;

        ////////////////////////
        // 3. Derive values
        ////////////////////////
        // b.
        let alpha_vecs = concat_slices(&l2_alphas, &vec![vec![F::zero(); log_n]; l1]);

        let gamma_eq_evals = compute_hypercube_eq_evals(log_l, &gamma_sumcheck);

        let zeta_0 = scale_and_sum(&alpha_vecs, &gamma_eq_evals);

        // compute \eta_{s + k}
        let mut nu_s_t = vec![F::default(); self.config.t];
        for (i, v_jk) in proof.shift_query_answers.iter().enumerate() {
            let res = v_jk
                .iter()
                .zip(&gamma_eq_evals)
                .fold(F::zero(), |acc, (v, eq)| acc + *eq * *v);
            nu_s_t[i] = res;
        }

        nus.extend(nu_s_t);

        // d. set \sigma^{(1)} and \sigma^{(2)}
        // compute eq(\tau, i) and eq(\xi, i)
        let tau_eq_evals = compute_hypercube_eq_evals(log_l, &tau);

        let etas = concat_slices(&l2_etas, &vec![F::zero(); l1]);

        let sigma_1 = tau_eq_evals
            .into_iter()
            .zip(l2_mus.into_iter().chain(l1_mus.to_vec()).zip(etas))
            .fold(F::zero(), |acc, (eq_tau, (mu, eta))| {
                acc + eq_tau * (mu + omega * eta)
            });

        let xi_eq_evals = compute_hypercube_eq_evals(log_r, &xi);

        let sigma_2 = xi_eq_evals
            .iter()
            .zip(&nus)
            .fold(F::zero(), |acc, (xi_eq, nu)| acc + *xi_eq * nu);

        ////////////////////////
        // 4. Decision phase
        ////////////////////////
        // a. new code evaluation point
        (acc_instance.alpha[0] == alpha_sumcheck).ok_or_err(VerifierError::CodeEvaluationPoint)?;

        // b. new circuit evaluation point
        let betas = l2_taus
            .into_iter()
            .chain(l1_taus)
            .zip(l2_xs.clone().into_iter().chain(l1_xs))
            .map(|(tau, x)| concat_slices(&tau, &x))
            .collect::<Vec<Vec<F>>>();
        let beta = scale_and_sum(&betas, &gamma_eq_evals);
        let expected_beta = concat_slices(&acc_instance.beta.0[0], &acc_instance.beta.1[0]);
        (expected_beta == beta).ok_or_err(VerifierError::CircuitEvaluationPoint)?;

        // c. proximity: check ark-vc openings (one pruned proof per tree).
        let queries: QueryIndices<F> =
            QueryIndices::from_squeezed_bytes(&bytes_shift_queries, log_n, self.config.t);

        proximity::verify::<F, H>(
            &self.scheme,
            &queries,
            &rt_0,
            &l2_roots,
            &proof.auth_0,
            &proof.auth_j,
            &proof.shift_query_answers,
            l1,
            l2,
            self.config.t,
        )?;

        // d. sumcheck decisions: reduce each transcript's round messages to
        // a single target, then compare to the expected claim in (e).
        (coeffs_twinc_sumcheck.len() == log_l).ok_or_err(VerifierError::NumSumcheckRounds)?;
        let target_1 =
            twin_constraint::verify_claim(sigma_1, coeffs_twinc_sumcheck, &gamma_sumcheck);

        (sums_batching_sumcheck.len() == log_n).ok_or_err(VerifierError::NumSumcheckRounds)?;
        let target_2 = batching::verify_claim(sigma_2, sums_batching_sumcheck, &alpha_sumcheck);

        // e. new target decision
        // build eq^{\star}(\alpha)
        (eq_poly_non_binary(&tau, &gamma_sumcheck) * (nus[0] + omega * eta) == target_1)
            .ok_or_err(VerifierError::Target)?;

        let mut zeta_eqs = vec![eq_poly_non_binary(&zeta_0, &alpha_sumcheck)];

        zeta_eqs.extend(
            ood_samples
                .chunks(log_n)
                .map(|zeta| eq_poly_non_binary(zeta, &alpha_sumcheck))
                .collect::<Vec<F>>(),
        );
        zeta_eqs.extend(
            queries
                .evaluation_points
                .iter()
                .map(|zeta| eq_poly_non_binary(zeta, &alpha_sumcheck))
                .collect::<Vec<F>>(),
        );
        (zeta_eqs.len() == r).ok_or_err(VerifierError::NumShiftQueries)?;

        // mul by \mu and compare to target_2
        (acc_instance.mu[0]
            * zeta_eqs
                .into_iter()
                .zip(xi_eq_evals)
                .fold(F::zero(), |acc, (a, b)| acc + a * b)
            == target_2)
            .ok_or_err(VerifierError::Target)?;

        Ok(())
    }

    fn decide(
        &self,
        acc_witness: AccumulatorWitness<F, H>,
        acc_instance: AccumulatorInstance<F, H>,
    ) -> Result<(), WARPError> {
        // Rebuild the Merkle tree from the stored witness and compare
        // against the accumulator's root, and also against the stored
        // trapdoor's own root (belt and suspenders — covers cases where
        // the trapdoor was tampered with but the root claim is consistent).
        let leaves: Vec<Vec<F>> = acc_witness.f[0].iter().map(|&x| vec![x]).collect();
        let computed = self.scheme.commit(&leaves);
        (&acc_instance.rt[0] == computed.root()).ok_or_err(DeciderError::MerkleRoot)?;
        (acc_witness.td[0].root() == computed.root()).ok_or_err(DeciderError::MerkleTrapDoor)?;

        let f_hat = DenseMultilinearExtension::from_evaluations_slice(
            log2(self.code.code_len()) as usize,
            &acc_witness.f[0],
        );
        (f_hat.evaluate(&acc_instance.alpha[0]) == acc_instance.mu[0])
            .ok_or_err(DeciderError::MLExtensionEvaluation)?;

        let tau = &acc_instance.beta.0[0];

        let tau_prep = EqPolyPrep::new(tau);
        let tau_zero_evader = Hypercube::<AscendingOrder>::new(tau.len())
            .map(|(index, _point)| tau_prep.eval(index))
            .collect::<Vec<F>>();

        let mut z = acc_instance.beta.1[0].clone();
        z.extend(acc_witness.w[0].clone());
        let computed_eta = self
            .p
            .evaluate_bundled(&tau_zero_evader, &z)
            .map_err(|_| DeciderError::BundledEvaluationFailed)?;
        (computed_eta == acc_instance.eta[0]).ok_or_err(DeciderError::BundledEvaluation)?;

        let computed_f = self.code.encode(&acc_witness.w[0]);
        (acc_witness.f[0] == computed_f).ok_or_err(DeciderError::EncodedWitness)?;

        Ok(())
    }
}
